{"content": """"Process-local NumPy 1.x alias shim, so the old xarray source (pre-NumPy-2)
can be imported under numpy 2.5.4 for verification only. Not part of the repo."""
import numpy as np

_aliases = {
    "unicode_": "str_",
    "float_": "float64",
    "complex_": "complex128",
    "bool8": "bool_",
    "object0": "object_",
    "NaN": "nan",
    "Inf": "inf",
    "Infinity": "inf",
    "infty": "inf",
    "NAN": "nan",
    "INF": "inf",
    "PINF": "inf",
    "NINF": None,  # handled below
}
for old, new in _aliases.items():
    if hasattr(np, old):
        continue
    if new is None:
        setattr(np, old, -np.inf)
    else:
        try:
            setattr(np, old, getattr(np, new))
        except AttributeError:
            pass
